// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 timeSeed) public {
        // Fuzz a non-bank actor who plays; bank is the deployer (this contract).
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0); // keep actor as EOA, not a helper
        vm.warp(timeSeed);
        vm.roll(timeSeed);
        vm.deal(actor, 10);

        uint256 bankBefore = address(this).balance;
        bool ok;
        vm.prank(actor);
        try c.play{value: 10}() { ok = true; } catch { ok = false; }
        uint256 bankAfter = address(this).balance;

        // TICKET_AMOUNT = 10, FEE_AMOUNT = 1.
        // pot() == 0 exactly when the payout branch executed: bank fee paid,
        // and actor received pot - FEE_AMOUNT. Here pot is 10, so actor receives 9.
        // Reference: bank gains exactly FEE_AMOUNT = 1 when payout branch runs.
        // Mutant: bank gains 0 in that same branch.
        if (ok && c.pot() == 0) {
            assertTrue(bankAfter - bankBefore == 1);
        } else {
            // No payout branch: no fee should move to bank in either version.
            assertTrue(bankAfter - bankBefore == 0);
        }
    }
}
